<?php defined('BASEPATH') OR exit('No direct script access allowed'); $types=['book'=>'Buku digital','manuscript'=>'Naskah / manuskrip','research'=>'Hasil riset','scientific_paper'=>'Karya ilmiah','thesis'=>'Skripsi','dissertation'=>'Tesis / disertasi','teaching_material'=>'Materi pembelajaran','other'=>'Lainnya'];$statuses=['pending'=>'Menunggu','reviewing'=>'Ditinjau','accepted'=>'Diterima','revision_requested'=>'Perlu perbaikan','rejected'=>'Ditolak'];$colors=['pending'=>'bg-yellow-lt text-yellow','reviewing'=>'bg-azure-lt text-azure','accepted'=>'bg-green-lt text-green','revision_requested'=>'bg-orange-lt text-orange','rejected'=>'bg-red-lt text-red'];$query=$_GET;unset($query['page']);$pageurl=function($p)use($query){return base_url('digital-donations?'.http_build_query(array_merge($query,['page'=>$p])));}; ?>
