ass="form-select" name="status"><option value="">Semua</option><?php foreach($statuses as $key=>$label):?><option value="<?=$key;?>" <?=$filters['status']===$key?'selected':'';?>><?=$label;?></option><?php endforeach;?></select></div><div class="col-6 col-md-3"><label class="form-label">Jenis</label><select class="form-select" name="type"><option value="">Semua</option><?php foreach($types as $key=>$label):?><option value="<?=$key;?>" <?=$filters['type']===$key?'selected':'';?>><?=$label;?></option><?php endforeach;?></select></div><div class="col-auto btn-list"><button class="btn btn-primary"><i class="ti ti-filter me-1"></i>Filter</button><a class="btn btn-outline-secondary" href="<?=base_url('digital-donations');?>">Reset</a></div><?=form_close();?></div><div class="table-responsive"><table class="table table-vcenter card-table"><thead><tr><th>Karya / Lisensi</th><th>Donor</th><th>Sumber Berkas</th><th>Status</th><th>Dikirim</th><th>Aksi</th></tr></thead><tbody><?php if(empty($items)):?><tr><td colspan="6" class="text-center text-secondary py-4">Belum ada usulan donasi dengan filter ini.</td></tr><?php endif;?><?php foreach($items as $item):?><tr><td><div class="fw-semibold"><?=html_escape($item['title']);?></div><div class="small text-secondary"><?=html_escape($types[$item['contribution_type']]??$item['contribution_type']);?><?= $item['creator_names']?' · '.html_escape($item['creator_names']):'';?></div><span class="badge bg-indigo-lt text-indigo mt-1"><?=strtoupper(str_replace('_',' ',$item['license_code']));?></span></td><td><div><?=html_escape($item['donor_name']);?></div><div class="small text-secondary"><?=html_escape($item['donor_email']?:$item['donor_phone']?:'-');?></div></td><td><?php if($item['file_path']):?><a class="btn btn-sm btn-outline-primary" target="_blank" href="<?=base_url('digital-donations/file/'.(int)$item['id']);?>"><i class="ti ti-file me-1"></i><?=html_escape($item['file_original_name']?:'Berkas');?></a><?php endif;?><?php if($item['external_url']):?><a class="btn btn-sm btn-outline-secondary ms-1" target="_blank" rel="noopener noreferrer" href="<?=html_escape($item['external_url']);?>"><i class="ti ti-link"></i></a><?php endif;?></td><td><span class="badge <?=$colors[$item['status']]??'bg-secondary-lt';?>"><?=$statuses[$item['status']]??$item['status'];?></span><?php if($item['admin_note']):?><div class="small text-secondary mt-1 text-truncate" style="max-width:220px"><?=html_escape($item['admin_note']);?></div><?php endif;?></td><td class="small"><?=date('d M Y H:i',strtotime($item['created_at']));?></td><td><?php if($can_review):?><button type="button" class="btn btn-sm btn-primary" data-bs-toggle="modal" data-bs-target="#review-<?= (int)$item['id'];?>"><i class="ti ti-clipboard-check me-1"></i>Tindak Lanjut</button><?php endif;?></td></tr><?php if($can_review):?><div class="modal modal-blur fade" id="review-<?= (int)$item['id'];?>" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><?=form_open('digital-donations/review/'.(int)$item['id']);?><div class="modal-header"><h5 class="modal-title">Tindak Lanjut Donasi</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="mb-2 fw-semibold"><?=html_escape($item['title']);?></div><div class="small text-secondary mb-3"><?=html_escape($item['donor_name']);?> · <?=html_escape($types[$item['contribution_type']]??$item['contribution_type']);?></div><label class="form-label">Status</label><select class="form-select mb-3" name="status"><?php foreach($statuses as $key=>$label):?><option value="<?=$key;?>" <?=$item['status']===$key?'selected':'';?>><?=$label;?></option><?php endforeach;?></select><label class="form-label">Catatan petugas</label><textarea class="form-control" rows="4" name="admin_note" placeholder="Hasil pemeriksaan lisensi, kelengkapan, atau tindak lanjut yang diperlukan."><?=html_escape($item['admin_note']);?></textarea></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary"><i class="ti ti-device-floppy me-1"></i>Simpan Tindak Lanjut</button></div><?=form_close();?></div></div></div><?php endif;?><?php endforeach;?></tbody></table></div><div class="card-footer responsive-footer"><span class="text-secondary small">Menampilkan <?=number_format($pagination['total']?$pagination['offset']+1:0,0,',','.');?>–<?=number_format(min($pagination['offset']+$pagination['per_page'],$pagination['total']),0,',','.');?> dari <?=number_format($pagination['total'],0,',','.');?> usulan</span><div class="btn-group"><a class="btn btn-sm btn-outline-secondary <?=$pagination['page']<=1?'disabled':'';?>" href="<?=$pageurl(max(1,$pagination['page']-1));?>">Sebelumnya</a><a class="btn btn-sm btn-outline-secondary <?=$pagination['page']>=$pagination['pages']?'disabled':'';?>" href="<?=$pageurl(min($pagination['pages'],$pagination['page']+1));?>">Berikutnya</a></div></div></div></div></div>
